[
  {
    "text": "MedPMC curated 11 million medical image-text pairs from 6.1 million PMC articles.",
    "topic": "MedPMC data curation"
  },
  {
    "text": "MedPMC achieved an F1 score of 93.2 for initial screening of medical image-text pairs.",
    "topic": "MedPMC performance"
  },
  {
    "text": "Manual review found 95.3% of MedPMC images medically relevant, compared to 19.7% in a prior PMC-derived dataset.",
    "topic": "MedPMC medical relevance"
  },
  {
    "text": "A MedPMC-trained CLIP-style model improved average zero-shot AUC by 7.1 percentage points over the strongest architecture-matched biomedical CLIP baseline.",
    "topic": "MedPMC model performance"
  },
  {
    "text": "In 10,524 Yale New Haven Health System dermatology photographs, MedPMC improved morphology-to-image retrieval Recall@5 by 11.7 percentage points.",
    "topic": "MedPMC clinical application"
  }
]
